/bin/zsh -lc "node - <<'NODE'
const fs = require('fs')
const file = 'iteration-17/eval-2-script-json-adaptation/no_skill/outputs/user-profile.mpx'
const source = fs.readFileSync(file, 'utf8')
const match = source.match(/<script type=\"application\\/json\">([\\s\\S]*?)<\\/script>/)
if ("'!match) throw new Error('"'application/json block missing')
function preprocess (text, mode) {
  const lines = text.split('\\n')
  const result = []
  let include = true
  const stack = []
  lines.forEach((line) => {
    if (line.includes('@mpx-if')) {
      stack.push(include)
      include = include && line.includes("'`mode === '"'"'${mode}'"'"'`)
    } else if (line.includes('"'@mpx-else')) {
      include = stack[stack.length - 1] && "'!include
    } else if (line.includes('"'@mpx-endif')) {
      include = stack.pop()
    } else if (include) {
      result.push(line)
    }
  })
  return result.join('\\n')
}
;['wx', 'ios'].forEach((mode) => JSON.parse(preprocess(match[1], mode)))
const required = ['<template>', '<script>', '<style lang=\"less\">', '<script type=\"application/json\">']
required.forEach((block) => {
  if ("'!source.includes(block)) throw new Error(`${block} missing`)
})
console.log(`validated ${file}: wx/ios JSON valid, SFC blocks complete, ${source.split('"'\\n').length} lines"'`)
NODE'

